package parser_test

// Parser fuzz: ParseSource must return errors, never panic, on arbitrary
// input. Run:
//
//	go test ./internal/parser -fuzz=FuzzParseSource -fuzztime=60s

import (
	"testing"

	"github.com/nodecoda/ncoda/pkg/parser"
)

func FuzzParseSource(f *testing.F) {
	seeds := []string{
		"",
		"@language nodecoda/1\n@mode workflow\nfunction main() {\n    return \"hi\";\n}\n",
		"@mode advanced-chat\n@conversation string name\nfunction main(string q) {\n    output(\"answer\", q);\n}\n",
		"function f(int a, int b) -> int { return a + b; }",
		"let x = { \"a\": [1, 2, { \"b\": true }] };",
		"type T = { string a; int b; }",
		"foreign code rust( string text = \"x\" ) -> { a: int; } { source `fn main() {}`; };",
		"function main() {",
		"@",
		"`\n",
		"function main() { let x = ; return x; }",
		"enum E { a, b, c }\nfunction main() -> E { return E.a; }",
		"for (let i = 0; i < 10; i += 1) { output(\"n\", i); }",
		"parallel { branch { let x = 1; } branch { let y = 2; } }",
		"attempt { let r = http(\"GET\", \"https://x\"); } recover { }",
		"request_input { title \"Q\" fields { name: string } }",
		"let f = function (int x) -> int { return x; };",
		"if (x) { } else if (y) { } else { }",
		"while (true) { break; }",
		"{{ template ${x} }}",
		// ── compound assignment: exercises deepCopyExpr/deepCopyNode ──
		"function main() { let x = 1; x += 1; x -= 2; x *= 3; x /= 4; return x; }",
		"function main() { let m = { \"a\": 1 }; m.a += 1; m[\"b\"] -= 2; return m; }",
		"function main() { let a = [1, 2]; a[0] *= 3; a[1] /= 2; return a; }",
		"function main() { let s = \"x\"; s += \"y\"; return s; }",
		"function main() { let x = 1; x += (2 + 3) * (4 - 1) / 2; }",
		"function main() { let t = { a: { b: { c: 1 } } }; t.a.b.c += 1; }",
		// ── while / loop state (incl. nested, compound in body) ──
		"function main() { let x = 0; while (x < 3) { x = x + 1; } return x; }",
		"function main() { let x = 0; while (x < 3) { x += 1; } return x; }",
		"function main() { let x = 0; while (x < 2) { let y = 0; while (y < 2) { y = y + 1; x = x + y; } } }",
		// ── hostile bytes / unicode / deep nesting ──
		"function main() { let s = \"\\x00\\x01\\xff\\xfe\\ud800\\udc00\\x7f\"; }",
		"function main() { let s = \"中文测试日本語한국어🚀emoji😀\"; return s; }",
		"function main() { let x = ((((((((((((((((((((1))))))))))))))))))))); }",
		"let  = 1;",
		"function main() { let  = ; }",
		"function main() { let x = 0; while (x < 1000000) { x += 1; } }",
		"function main() { let x = 99999999999999999999999999999999999999; }",
		"function main() { let f = 1.7976931348623157e308; let g = 5e-324; }",
		"function main() { let s = \"\\x00\" + \"\\xff\"; }",
		"@mode workflow\n@conversation string q\nfunction main(string q) { output(\"a\", q); }",
	}
	for _, s := range seeds {
		f.Add([]byte(s))
	}
	f.Fuzz(func(t *testing.T, input []byte) {
		_, _ = parser.ParseSource(string(input), "fuzz.ncoda") // must not panic
	})
}
